ST.xhtml:p:
R_Trriger1(CLK := g_biFixedLenAbsOpen);
R_Trriger2(CLK := g_biFixedLenAbsClose);

IF R_Trriger1.Q THEN
  g_boFixedLenAbsDone := FALSE;
  nSwitchState := 1;
END_IF;

IF R_Trriger2.Q THEN
  g_boFixedLenAbsDone := FALSE;
END_IF;


CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  FixedLenAbs.Execute := FALSE;
  IF LREAL_TO_INT(g_fiFixedLenAxisType) = 0 THEN
    dSafeDis := dPartFixedLenDis - g_dBKheadLength;
    IF dSafeDis <= 5.0 THEN
      FixedLenAbs.Position := 5.0;
    ELSE
      FixedLenAbs.Position := dSafeDis;
    END_IF;
    g_nBKCuttingState := 1;
  ELSIF LREAL_TO_INT(g_fiFixedLenAxisType) = 1 THEN
    FixedLenAbs.Position := dPartFixedLenDis - g_dBKPartLength;
    g_nBKCuttingState := 13;
  ELSIF LREAL_TO_INT(g_fiFixedLenAxisType) = 2 THEN
    nPartNum := TRUNC(g_noRemainPartCount);
    dTailFixedLenDis := g_dPipeRemainTailLen - INT_TO_LREAL(nPartNum)*g_dBKPartLength;
    FixedLenAbs.Position := dPartFixedLenDis - dTailFixedLenDis - 30.0;
    g_nBKCuttingState := 23;
  END_IF;
  nSwitchState := 2;
  2:
  FixedLenAbs.Execute := TRUE;
  FixedLenAbs.Velocity := dVelocity;

  IF FixedLenAbs.Done THEN
    FixedLenAbs.Execute := FALSE;
    g_boFixedLenAbsDone := TRUE;
    g_nBKCuttingState := 2;
    nSwitchState := 0;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 10;
  END_IF;
  IF FixedLenAbs.CommandAborted OR FixedLenAbs.Error THEN
    g_boFixedLenAbsDone := FALSE;
    FixedLenAbs.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
  10:
  FixedLenAbs.Execute := FALSE;
  FixedLen_Stop.Execute := TRUE;
  IF FixedLen_Stop.Done AND g_bPlcStartBuffer THEN
    FixedLen_Stop.Execute := FALSE;
    nSwitchState := 1;
  END_IF;

  IF FixedLen_Stop.CommandAborted OR FixedLen_Stop.Error THEN
    FixedLen_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  FixedLenAbs.Execute := FALSE;
  FixedLen_Stop.Execute := FALSE;
  nSwitchState := 0;
END_IF;
